    window.THEME_GROUPS = window.THEME_GROUP_META.map(function (g) {
        return { id: g.id, label: g.label, emoji: g.emoji, sub: g.sub || '', keys: Object.keys(window.THEMES).filter(function (k) { return window.THEMES[k].group === g.id; }) };
    });

    // ★ v11 — ARTIST WORLDS
    // The collection has two levels: an artist is a world (one identity, one
    // shared atmosphere), an album inside it is an era (its own palette, scene
    // and motion). The pickers render twArtistHero() above each artist's grid,
    // so profile and admin share the same markup and copy.
    window.TW_ARTIST_WORLDS = {
        taylor: {
            tag: 'The Eras Collection',
            blurb: 'A house with many rooms. Every record changes the light, the furniture and the weather, but the storytelling stays.',
            moods: ['golden hour', 'city pop', 'folk mist', 'showgirl neon']
        },
        olivia: {
            tag: 'The Emotional Scrapbook',
            blurb: 'Bedroom walls, torn notebook pages and a heart worn on the sleeve. Each era is a page you can step into.',
            moods: ['sour cherry', 'teenage riot', 'violet spill', 'carousel dusk']
        },
        ariana: {
            tag: 'The Dreamy Pop Universe',
            blurb: 'Glamour, haze and celestial light. Pop as a dream you can walk through, one album at a time.',
            moods: ['cloud nine', 'dangerous satin', 'sweetener sun', 'eternal glow']
        },
        conan: {
            tag: 'Cinematic Melancholy',
            blurb: 'Wide skies, empty parking lots and the last scene of a film. Quiet, intimate, and always a little heartbroken.',
            moods: ['suburban blue', 'velvet ache', 'neon chapel', 'wishbone grey']
        },
        maki: {
            tag: 'The OPM Romantic World',
            blurb: 'Golden dusk, sea air and the quiet ache of a Filipino love song — contemporary OPM turned into atmosphere.',
            moods: ['tanong dusk', 'saan sea', 'dilaw sun', 'kolorcoaster night']
        },
        lany: {
            tag: 'The Neon Night Drive',
            blurb: 'City lights on wet asphalt, a car stereo and a coastline at 2am. Every album is a different stretch of road.',
            moods: ['malibu blue', 'pink motel', 'midnight teal', 'soft daylight']
        }
    };

    window.twArtistWorld = function (groupId) {
        var raw = String(groupId || '');
        var id = raw.indexOf('artist_') === 0 ? raw.slice(7) : raw;
        var world = window.TW_ARTIST_WORLDS[id];
        if (!world) return null;
        return {
            id: id,
            tag: world.tag,
            blurb: world.blurb,
            moods: world.moods,
            keys: Object.keys(window.THEMES).filter(function (k) { return window.THEMES[k].group === 'artist_' + id; })
        };
    };

    window.twArtistHero = function (groupId) {
        var w = window.twArtistWorld(groupId);
        if (!w || !w.keys.length) return '';
        var meta = null;
        (window.THEME_GROUP_META || []).forEach(function (g) { if (g.id === 'artist_' + w.id) meta = g; });
        function esc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;')
                .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }
        var spines = w.keys.map(function (key, i) {
            var t = window.THEMES[key];
            return '<i style="--tw-spine:' + t.preview.gradient + ';--tw-r:' + ((i % 5) - 2) + '" title="' + esc(t.name) + '"></i>';
        }).join('');
        var moods = w.moods.map(function (m) { return '<li>' + esc(m) + '</li>'; }).join('');
        return '<section class="tw-world" data-tw-world="' + w.id + '" aria-label="' + esc(meta ? meta.label : w.id) + ' — ' + esc(w.tag) + '">'
            + '<span class="tw-world-glow" aria-hidden="true"></span>'
            + '<div class="tw-world-copy">'
            + '<span class="tw-world-eyebrow"><span aria-hidden="true">' + esc(meta ? meta.emoji : '') + '</span> Artist world <b>·</b> ' + w.keys.length + ' eras</span>'
            + '<h4 class="tw-world-title">' + esc(meta ? meta.label : w.id) + ' <em>' + esc(w.tag) + '</em></h4>'
            + '<p class="tw-world-blurb">' + esc(w.blurb) + '</p>'
            + '<ul class="tw-world-moods">' + moods + '</ul>'
            + '</div>'
            + '<div class="tw-world-spines" aria-hidden="true">' + spines + '</div>'
            + '</section>';
    };

    // Every album theme borrows the pointer badge of the scene whose palette
    // it is closest to.
    (function albumCursors() {
        var byArtist = { taylor: 'starry', olivia: 'crimson', ariana: 'nebula', conan: 'moonlit', maki: 'sunshine', lany: 'sakura' };
        Object.keys(window.THEMES).forEach(function (key) {
            if (window.THEMES[key].group.indexOf('artist_') !== 0) return;
            var artist = window.THEMES[key].group.slice(7);
            var from = byArtist[artist];
            if (!window.THEME_CURSORS[key] && from && window.THEME_CURSORS[from]) {
                window.THEME_CURSORS[key] = window.THEME_CURSORS[from];
            }
        });
    })();


