                P + ',' + P + ' *,' + P + ' *::before,' + P + ' *::after{' + decl(presetKey, 0, pal) + '}' +
                P + ' :is(' + HOVER + '){' + decl(presetKey, 1, pal) + '}' +
                P + ' :is(' + TEXT + '){cursor:text !important}' +
                P + ' :is(' + HOVER + '):active,' + P + ' *:active{' + decl(presetKey, 2, pal) + '}' +
                P + ' :is(' + TEXT + '):active{cursor:text !important}';
